js=r'''
const DEMO_KEY='stock-preview-functional-v21';const DEMO_NOW=new Date('2026-10-29T14:15:00+07:00');const USER='LÊ THỊ HƯƠNG TRÀ';let mode='staff',keyword='',statusChoice='',warehouseChoice='',selectedVIN='',drawerModel='',drawerSearch='',drawerStatus='',drawerVersion='',detailTab='specs',lastFocus=null,modalTarget='',modalAction='',toastTimer;
function seedVehicles(){const list=[];for(let i=0;i<20;i++){const status=i>=15?'Đã ghép':([0,1,14].includes(i)?'Đang giữ':'Chưa ghép');list.push({vin:i===0?'RLLVAG8C5TH835257':'RLLVAG8C5TH'+String(835257+i),model:'VF 6',version:i%3===0?'Plus':'Eco',color:'Urban Mint (CE1W)',interior:'Brown',image:'vf6-ce1w',engine:i===0?'VFBAJB26904008':'VFBAJB269'+String(4008+i).padStart(5,'0'),dms:'N31913',coc:'24-09-26 TT-OTO-'+String(835257+i)+'/2026/COC',warehouse:i%4===0?'QL2 (HCM)':'Kho Thuận An',parking:(i%4===0?'QL2':'A')+' · '+String(i+1).padStart(2,'0'),status,holder:status==='Chưa ghép'?'':i===1?USER:i===0?'NGUYỄN HOÀNG PHÚC':i>=15?'TRẦN MINH TUẤN':'NGUYỄN THỊ BÍCH TRÂM',expiry:status==='Đang giữ'?'2026-10-29T14:31:00+07:00':'',received:'2026-10-'+String(10+i%18).padStart(2,'0'),transport:i===3?'2026-10-29':'2026-10-20',location:i===3?'Đang vận tải':i%4===0?'QL2 (HCM)':'Kho Thuận An',coords:i===3?{lat:10.955,lng:106.705,address:'QL13, Thuận An, Bình Dương',speed:35,captured:'29/10/2026 14:10'}:null,realWarehouse:i===4?'Bãi vệ tinh An Phú':'',notes:i===0?'Xe đang giữ theo TVBH Nguyễn Hoàng Phúc.':i===3?'Xe đang vận tải về showroom.':'Đã kiểm tra tình trạng ngoại quan.',queue:i===0?['TRẦN THỊ NGỌC HÀ']:[],extension:false,order:i>=15?'N31913-VSO-26-10-'+String(120+i):'',logs:[{time:'29/10/2026 09:00',text:'Tiếp nhận thông tin xe và hồ sơ COC.'}]})}for(const [j,m]of ['VF 3','VF 5','VF 7','VF 8','LIMO'].entries())list.push({vin:'RLLVAGBC2TH'+String(819650+j),model:m,version:m==='LIMO'?'Green':'Plus',color:'White (CE18)',interior:'Black',image:m==='LIMO'?'limo-ce18':m.toLowerCase().replace(' ','')+'-ce18',engine:'VFCAJB267'+String(210268+j),dms:'N31913',coc:'24-10-26 TT-OTO-'+String(819650+j)+'/2026/COC',warehouse:'Kho Thuận An',parking:'B · '+String(j+1).padStart(2,'0'),status:'Chưa ghép',holder:'',expiry:'',received:'2026-10-24',transport:'2026-10-23',location:'Kho Thuận An',coords:null,realWarehouse:'',notes:'Xe đã kiểm tra ngoại quan.',queue:[],extension:false,order:'',logs:[{time:'24/10/2026 10:00',text:'Nhập kho Thuận An.'}]});return list}
let stock;try{const saved=JSON.parse(localStorage.getItem(DEMO_KEY));stock=Array.isArray(saved)?saved:seedVehicles()}catch{stock=seedVehicles()}
const rail=document.querySelector('.rail').outerHTML;document.body.innerHTML=`<div class="app">${rail}<section class="demo-main"><header class="demo-head"><div><h1>Kho xe <small id="total-count"></small></h1><p>VinFast Thuận An · Chọn dòng xe qua ảnh, thao tác theo từng VIN</p></div><div class="demo-settings"><label>Vai trò thử nghiệm <select id="role"><option value="staff">TVBH · Lê Thị Hương Trà</option><option value="admin">Quản trị viên</option><option value="readonly">Tài khoản chỉ xem</option></select></label><button class="btn" id="reset-demo">Đặt lại dữ liệu mẫu</button></div></header><div class="demo-banner"><span>BẢN THỬ TƯƠNG TÁC · Dữ liệu lưu riêng trong trình duyệt, không cập nhật kho thật.</span><span>VF 6 có 20 xe · Mốc giờ thử: 29/10/2026 14:15</span></div><div class="demo-toolbar"><label class="search">${icon('search')}<input id="stock-search" placeholder="Tìm VIN, dòng xe, số máy, mã DMS, COC, người giữ…" aria-label="Tìm kho xe"></label><select id="warehouse-filter" aria-label="Kho xe"><option value="">Tất cả kho</option><option>Kho Thuận An</option><option>QL2 (HCM)</option><option>Đang vận tải</option></select><button class="btn" id="export-demo">Xuất CSV ↗</button><span class="toolbar-right" id="stock-count"></span></div><div class="demo-tabs" id="stock-tabs"></div><div class="demo-gallery" id="stock-gallery"></div><footer class="demo-footer"><span>MẪU 21 · NHÓM XE + DANH SÁCH VIN ĐẦY ĐỦ</span><span>© 2026 ORDER MANAGEMENT</span></footer></section></div><div class="overlay" id="drawer-overlay" hidden><section class="vin-drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-heading"><div><h2 id="drawer-title"></h2><p id="drawer-subtitle"></p></div><button class="close-btn" id="close-drawer" aria-label="Đóng danh sách VIN">×</button></header><div class="drawer-tools"><label class="search">${icon('search')}<input id="drawer-search" placeholder="Tìm VIN, số máy, COC, người giữ…" aria-label="Tìm trong danh sách VIN"></label><select id="drawer-status" aria-label="Trạng thái VIN"><option value="">Tất cả trạng thái</option><option>Chưa ghép</option><option>Đang giữ</option><option>Đã ghép</option></select><select id="drawer-version" aria-label="Phiên bản VIN"><option value="">Tất cả phiên bản</option><option>Eco</option><option>Plus</option><option>Green</option></select><span class="count" id="drawer-count"></span></div><div class="drawer-body"><div class="vin-list" id="vin-list" aria-label="Danh sách VIN"></div><div class="vin-detail" id="vin-detail"></div></div><footer class="drawer-bottom"><span>Toàn bộ trường thông tin của thẻ Kho xe gốc</span><span>Thao tác thử · Không gửi yêu cầu thật</span></footer></section></div><dialog id="action-dialog" aria-labelledby="modal-title"><h3 id="modal-title"></h3><form id="action-form"><div class="modal-content" id="modal-content"></div><div class="modal-actions"><button type="button" class="btn" id="cancel-action">Hủy</button><button type="submit" class="btn primary" id="confirm-action">Xác nhận</button></div></form></dialog><div class="toast" id="toast" role="status" hidden></div>`;
const getVIN=vin=>stock.find(c=>c.vin===vin);const isMine=c=>c.holder===USER;const readonly=()=>mode==='readonly';const isNear=c=>c.expiry&&new Date(c.expiry)-DEMO_NOW>0&&new Date(c.expiry)-DEMO_NOW<=20*60000;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>value?new Date(value).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'}).replace(',',''):'—';
function message(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function persist(){try{localStorage.setItem(DEMO_KEY,JSON.stringify(stock))}catch{message('Không thể lưu mẫu vào trình duyệt. Thao tác vẫn có hiệu lực trong phiên này.')}}
function log(c,text){c.logs.unshift({time:'29/10/2026 14:15 · Thử nghiệm',text});persist()}
function matches(c,q){return Object.values(c).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(q.toLowerCase())}
function primaryActions(c,small=false){if(readonly())return '<span class="mode-note">Chỉ xem</span>';const cls=small?' small':'';const button=(action,label,primary=false)=>`<button class="btn${cls}${primary?' primary':''}" data-action="${action}" data-vin="${esc(c.vin)}">${label}</button>`;let out='';if(c.status==='Chưa ghép')out=button('hold','Giữ xe (24h)',true);else if(c.status==='Đang giữ'&&isMine(c))out=button('release','Nhả xe')+button('match','Ghép xe',true)+(isNear(c)||c.extension?button('extend',c.extension?'Chờ duyệt gia hạn':'Xin gia hạn'):'');else if(!isMine(c)){out=button(c.queue.includes(USER)?'leave':'queue',c.queue.includes(USER)?'Hủy chờ':'Đăng ký chờ');const own=stock.some(o=>o.vin!==c.vin&&isMine(o)&&o.status==='Đang giữ'&&o.model===c.model&&o.version===c.version&&o.color===c.color&&o.interior===c.interior);if(own&&(c.status==='Đang giữ'||c.status==='Đã ghép'))out+=button('swap','Đổi xe');if(mode==='admin'&&c.status==='Đang giữ')out+=button('release','Hủy giữ (Admin)')}if(mode==='admin'&&c.extension)out+=button('approve-extension','Duyệt gia hạn');return out}
function previewRow(c){return `<div class="preview-vin"><div class="vin-top"><span class="vin-text">${esc(c.vin)}<small>${esc(c.version)}</small></span><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></div><div class="vin-bottom"><span class="vin-location">${esc(c.location)}</span><div class="action-set"><button class="btn small" data-action="detail" data-vin="${c.vin}">Chi tiết</button>${primaryActions(c,true)}</div></div></div>`}
function filteredStock(){return stock.filter(c=>matches(c,keyword)&&(!statusChoice||c.status===statusChoice)&&(!warehouseChoice||c.location===warehouseChoice))}
function renderStock(){const visible=filteredStock();$('total-count').textContent=stock.length;$('stock-count').textContent=visible.length+' / '+stock.length+' xe';$('stock-tabs').innerHTML=['','Chưa ghép','Đang giữ','Đã ghép'].map(s=>`<button class="${s===statusChoice?'on':''}" data-stock-status="${s}">${s||'Tất cả xe'}<small>${s?stock.filter(c=>c.status===s).length:stock.length}</small></button>`).join('');const groups=[...new Set(visible.map(c=>c.model))];$('stock-gallery').innerHTML=groups.map(m=>{const group=visible.filter(c=>c.model===m);const all=stock.filter(c=>c.model===m);const c=group[0];return `<section class="group-card"><div class="group-heading"><h2>${m}</h2><small>${all.length} xe · ${all.filter(c=>c.status==='Chưa ghép').length} chưa ghép</small></div><button class="group-photo" data-open-model="${m}" aria-label="Xem tất cả ${all.length} xe ${m}"><img src="../pictures/${c.image}.webp" alt="${m}"></button><div class="group-color"><span>${esc(c.color)} / ${esc(c.interior)}</span><span>${all.filter(c=>c.status==='Đang giữ').length} giữ · ${all.filter(c=>c.status==='Đã ghép').length} ghép</span></div>${group.slice(0,3).map(previewRow).join('')}<button class="group-more" style="width:100%" data-open-model="${m}"><span>Xem đầy đủ ${all.length} xe →</span><small>${group.length>3?'Còn '+(group.length-3)+' xe':''}</small></button></section>`}).join('')||'<div class="empty-result">Không tìm thấy xe. Hãy thay đổi từ khóa hoặc bộ lọc.</div>';document.querySelectorAll('[data-stock-status]').forEach(b=>b.onclick=()=>{statusChoice=b.dataset.stockStatus;renderStock()});document.querySelectorAll('[data-open-model]').forEach(b=>b.onclick=()=>openDrawer(b.dataset.openModel));bindActions($('stock-gallery'))}
function openDrawer(model,vin=''){lastFocus=document.activeElement;drawerModel=model;drawerSearch='';drawerStatus='';drawerVersion='';$('drawer-search').value='';$('drawer-status').value='';$('drawer-version').value='';selectedVIN=vin||stock.find(c=>c.model===model)?.vin||'';detailTab='specs';$('drawer-overlay').hidden=false;renderDrawer();$('close-drawer').focus()}
function closeDrawer(){$('drawer-overlay').hidden=true;lastFocus?.focus()}
function drawerVehicles(){return stock.filter(c=>c.model===drawerModel&&matches(c,drawerSearch)&&(!drawerStatus||c.status===drawerStatus)&&(!drawerVersion||c.version===drawerVersion))}
function renderDrawer(){if($('drawer-overlay').hidden)return;const all=stock.filter(c=>c.model===drawerModel);const visible=drawerVehicles();if(!visible.some(c=>c.vin===selectedVIN))selectedVIN=visible[0]?.vin||'';$('drawer-title').textContent=drawerModel+' · Danh sách VIN';$('drawer-subtitle').textContent=`${all.length} xe · ${all.filter(c=>c.status==='Chưa ghép').length} chưa ghép · ${all.filter(c=>c.status==='Đang giữ').length} đang giữ · ${all.filter(c=>c.status==='Đã ghép').length} đã ghép`;$('drawer-count').textContent=visible.length+' / '+all.length+' xe';$('vin-list').innerHTML=visible.map(c=>`<button class="list-vin ${c.vin===selectedVIN?'selected':''}" data-select-vin="${c.vin}"><span class="top"><strong>${esc(c.vin)}</strong><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></span><span class="meta"><span>${c.model} · ${c.version} · ${esc(c.interior)}</span><span>${esc(c.location)}</span></span><div class="holder">${c.holder?esc(c.holder)+(c.expiry?' · Hết hạn '+fmt(c.expiry):''):'Chưa có người giữ'}${c.queue.includes(USER)?' · Bạn đang đăng ký chờ':''}</div></button>`).join('')||'<div class="empty-result">Không tìm thấy VIN phù hợp.</div>';$('vin-list').querySelectorAll('[data-select-vin]').forEach(b=>b.onclick=()=>{selectedVIN=b.dataset.selectVin;detailTab='specs';renderDrawer()});renderDetail()}
function detailFields(c){return [['Dòng xe',c.model+' - '+c.version],['Màu sắc',c.color+' / '+c.interior],['Số VIN',c.vin,'copy'],['Số máy',c.engine,'copy'],['Mã DMS',c.dms,'copy'],['Số COC',c.coc,'copy'],['Kho xe',c.warehouse],['Vị trí hiện tại',c.location],['Vị trí đỗ',c.parking],['Bãi thực tế',c.realWarehouse||'—'],['Trạng thái',c.status],['Người giữ',c.holder||'—'],['Thời hạn',c.expiry?fmt(c.expiry):'—'],['Ngày nhập kho',c.received.split('-').reverse().join('/')],['Ngày vận tải',c.transport?c.transport.split('-').reverse().join('/'):'—'],['Mã phiên bản',c.model.replace(' ','')+'-'+c.version.toUpperCase()],['Đơn hàng',c.order||'Chưa ghép đơn'],['Ghi chú DMS',c.notes||'—']]}
function renderDetail(){const c=getVIN(selectedVIN);if(!c){$('vin-detail').innerHTML='<div class="empty-result">Chọn một VIN để xem đầy đủ thông tin.</div>';return}let content='';if(detailTab==='specs')content=`<div class="detail-section-title"><span>THÔNG SỐ XE</span>${mode==='admin'?`<button class="btn" data-action="edit" data-vin="${c.vin}">✎ Chỉnh sửa</button>`:''}</div>${detailFields(c).map(([label,value,type])=>`<div class="field-row"><span class="field-label">${label}</span>${type==='copy'?`<button class="copy-value" data-copy="${esc(value)}" title="Sao chép ${label}">${esc(value)}</button>`:`<span class="field-value">${esc(value)}</span>`}</div>`).join('')}${c.coords?`<div class="field-row"><span class="field-label">GPS vận tải</span><button class="copy-value" data-action="map" data-vin="${c.vin}">${esc(c.coords.address)} ↗</button></div>`:''}<div class="detail-actions">${primaryActions(c)}${mode==='admin'?`<button class="btn danger" data-action="delete" data-vin="${c.vin}">Xóa xe khỏi mẫu</button>`:''}</div><div class="queue-box"><div style="display:flex;justify-content:space-between;align-items:center"><strong>Hàng chờ · ${c.queue.length} người</strong>${!readonly()&&!isMine(c)&&c.status!=='Chưa ghép'?`<button class="btn small" role="switch" aria-checked="${c.queue.includes(USER)}" data-action="${c.queue.includes(USER)?'leave':'queue'}" data-vin="${c.vin}">${c.queue.includes(USER)?'Đang chờ · Hủy':'Đăng ký chờ'}</button>`:''}</div>${c.queue.length?c.queue.map((name,i)=>`<div class="queue-person"><span>${i+1}. ${esc(name)}</span><span>${name===USER?'Bạn':''}</span></div>`).join(''):'Chưa có người đăng ký chờ.'}<div style="margin-top:7px">Nhả xe sẽ chuyển lượt theo thứ tự FIFO trong dữ liệu thử.</div></div>`;else content=c.logs.map(l=>`<div class="log-entry"><time>${esc(l.time)}</time>${esc(l.text)}</div>`).join('');$('vin-detail').innerHTML=`<div class="detail-hero"><img src="../pictures/${c.image}.webp" alt="${c.model}"><div><h3>${c.model} <small>${c.version}</small></h3><p>${esc(c.color)} / ${esc(c.interior)}</p><p style="margin-top:9px;color:${tone(c.status)}">● ${c.status}${isMine(c)?' · Tôi đang giữ':''}</p></div></div><div class="detail-tabs"><button data-detail-tab="specs" class="${detailTab==='specs'?'on':''}">Thông số & tác nghiệp</button><button data-detail-tab="logs" class="${detailTab==='logs'?'on':''}">Nhật ký (${c.logs.length})</button></div>${content}`;bindActions($('vin-detail'));$('vin-detail').querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);message('Đã sao chép đầy đủ: '+b.dataset.copy)}catch{message('Giá trị cần sao chép: '+b.dataset.copy)}});$('vin-detail').querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detailTab;renderDetail()})}
function refresh(){persist();renderStock();renderDrawer()}
function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();const c=getVIN(b.dataset.vin);if(!c)return;if(b.dataset.action==='detail'){openDrawer(c.model,c.vin);return}if(readonly()){message('Tài khoản chỉ xem không được thay đổi dữ liệu.');return}showAction(c,b.dataset.action)})}
function showAction(c,action){modalTarget=c.vin;modalAction=action;let title='',body='',submit='Xác nhận';const input=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required></label>`;if(action==='hold'){title='Giữ xe trong 24 giờ';body='Xe sẽ được giữ cho '+USER+'. Nếu ngày hết hạn rơi vào Chủ nhật, thời hạn được cộng thêm 24 giờ.'}else if(action==='release'){title=mode==='admin'&&!isMine(c)?'Hủy giữ xe (Quản trị viên)':'Nhả xe';body='Xe sẽ chuyển cho người đầu hàng chờ; nếu chưa có hàng chờ sẽ trở về Chưa ghép.'}else if(action==='queue'){title='Đăng ký hàng chờ';body='Bạn sẽ ở vị trí '+(c.queue.length+1)+' trong hàng chờ của VIN này.'}else if(action==='leave'){title='Hủy đăng ký chờ';body='Bạn sẽ được gỡ khỏi hàng chờ của VIN này.'}else if(action==='extend'){title=c.extension?'Yêu cầu gia hạn đã gửi':'Xin gia hạn giữ xe';body=c.extension?'Yêu cầu đang chờ quản trị viên duyệt.':input('reason','Lý do xin gia hạn')+'<p>Gửi yêu cầu gia hạn thêm 24 giờ để quản trị viên xem xét.</p>';submit=c.extension?'Đóng':'Gửi yêu cầu'}else if(action==='approve-extension'){title='Duyệt gia hạn 24 giờ';body='Cộng thêm 24 giờ vào thời hạn hiện tại. Nếu rơi vào Chủ nhật, cộng thêm 24 giờ.'}else if(action==='match'){title='Tạo yêu cầu ghép xe';body=input('customer','Tên khách hàng')+input('order','Số đơn hàng')+input('note','Ghi chú','Yêu cầu ghép xe trong bản thử');submit='Gửi yêu cầu mẫu'}else if(action==='swap'){title='Đề nghị đổi xe cùng cấu hình';const own=stock.filter(o=>o.vin!==c.vin&&isMine(o)&&o.status==='Đang giữ'&&o.model===c.model&&o.version===c.version&&o.color===c.color&&o.interior===c.interior);body=`<label>Xe của bạn (cùng dòng, phiên bản và màu)<select name="source" required>${own.map(o=>`<option value="${o.vin}">${o.vin} · ${o.version}</option>`).join('')}</select></label>`+input('reason','Lý do đề nghị đổi')+'<p>Ghi nhận đề nghị trong nhật ký, không tự đổi chủ giữ xe.</p>'}else if(action==='edit'){title='Chỉnh sửa thông tin xe (Admin)';body=input('vin','Số VIN (17 ký tự)',c.vin)+input('model','Dòng xe',c.model)+input('version','Phiên bản',c.version)+input('color','Ngoại thất',c.color)+input('interior','Nội thất',c.interior)+input('engine','Số máy',c.engine)+input('dms','Mã DMS',c.dms)+input('coc','Số COC',c.coc)+input('warehouse','Kho quản lý',c.warehouse)+input('location','Vị trí hiện tại',c.location)+input('parking','Vị trí đỗ',c.parking)+input('notes','Ghi chú DMS',c.notes);submit='Lưu dữ liệu mẫu'}else if(action==='delete'){title='Xóa xe khỏi dữ liệu mẫu';body=input('reason','Lý do xóa')+'<p>Chỉ xóa bản ghi trong trình duyệt. Có thể khôi phục bằng Đặt lại dữ liệu mẫu.</p>';submit='Xóa khỏi mẫu'}else if(action==='map'){title='Vị trí GPS vận tải';body=`<div class="map-schematic">📍 ${esc(c.coords.address)}</div><p>Tọa độ: ${c.coords.lat}, ${c.coords.lng}<br>Vận tốc: ${c.coords.speed} km/h<br>Cập nhật: ${c.coords.captured}</p><a href="https://www.google.com/maps?q=${c.coords.lat},${c.coords.lng}" target="_blank" rel="noopener" style="color:#205eb4">Mở tọa độ trên Google Maps ↗</a><p>Sơ đồ và GPS là dữ liệu minh họa.</p>`;submit='Đóng'}else return;$('modal-title').textContent=title;$('modal-content').innerHTML=`<div class="modal-vin">${esc(c.model)} ${esc(c.version)} · ${esc(c.vin)}</div>${body}<div class="modal-error" id="modal-error" role="alert"></div>`;$('confirm-action').textContent=submit;$('action-dialog').showModal()}
function guard(c,a){if(readonly())return false;if(['edit','delete','approve-extension'].includes(a))return mode==='admin';if(a==='hold')return c.status==='Chưa ghép';if(a==='release')return c.status==='Đang giữ'&&(isMine(c)||mode==='admin');if(['extend','match'].includes(a))return c.status==='Đang giữ'&&isMine(c);if(['queue','leave'].includes(a))return c.status!=='Chưa ghép'&&!isMine(c);return true}
function plusDay(value){const d=new Date(value);d.setTime(d.getTime()+24*60*60*1000);if(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Ho_Chi_Minh',weekday:'short'}).format(d)==='Sun')d.setTime(d.getTime()+24*60*60*1000);return d.toISOString()}
$('action-form').onsubmit=e=>{e.preventDefault();const c=getVIN(modalTarget),a=modalAction;if(!c)return;if(!guard(c,a)){$('modal-error').textContent='Trạng thái hoặc quyền hiện tại không cho phép thao tác này.';return}const data=Object.fromEntries(new FormData(e.target));if(a==='hold'){c.status='Đang giữ';c.holder=USER;c.expiry=plusDay(DEMO_NOW);log(c,'TVBH '+USER+' giữ xe 24 giờ.')}else if(a==='release'){const next=c.queue.shift();c.status=next?'Đang giữ':'Chưa ghép';c.holder=next||'';c.expiry=next?plusDay(DEMO_NOW):'';c.extension=false;log(c,next?'Nhả xe, chuyển lượt cho '+next+' theo FIFO.':'Nhả xe, xe trở về Chưa ghép.')}else if(a==='queue'){if(!c.queue.includes(USER))c.queue.push(USER);log(c,USER+' đăng ký hàng chờ.')}else if(a==='leave'){c.queue=c.queue.filter(n=>n!==USER);log(c,USER+' hủy hàng chờ.')}else if(a==='extend'){if(!c.extension){if(!data.reason?.trim()){$('modal-error').textContent='Nhập lý do xin gia hạn.';return}c.extension=true;log(c,'Xin gia hạn 24 giờ: '+data.reason.trim())}}else if(a==='approve-extension'){if(!c.extension){$('modal-error').textContent='Không có yêu cầu gia hạn để duyệt.';return}c.expiry=plusDay(c.expiry);c.extension=false;log(c,'Quản trị viên duyệt gia hạn thêm 24 giờ.')}else if(a==='match'){if(!data.customer?.trim()||!data.order?.trim()){$('modal-error').textContent='Nhập đầy đủ khách hàng và số đơn hàng.';return}c.request={customer:data.customer.trim(),order:data.order.trim(),note:data.note?.trim()};log(c,'Gửi yêu cầu ghép xe cho '+data.customer.trim()+' · '+data.order.trim()+'. Đang chờ phê duyệt; xe vẫn đang giữ.')}else if(a==='swap'){const source=getVIN(data.source);if(!source||!isMine(source)||source.status!=='Đang giữ'||source.model!==c.model||source.version!==c.version||source.color!==c.color||source.interior!==c.interior||!data.reason?.trim()){$('modal-error').textContent='Cần chọn xe đang giữ cùng cấu hình và nhập lý do.';return}log(c,'Đề nghị đổi từ '+source.vin+': '+data.reason.trim());log(source,'Đề nghị đổi sang '+c.vin+'. Đang chờ người giữ xe phản hồi.')}else if(a==='edit'){const newVIN=data.vin.trim().toUpperCase();if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(newVIN)||stock.some(o=>o!==c&&o.vin===newVIN)){$('modal-error').textContent='VIN phải có 17 ký tự hợp lệ và không trùng xe khác.';return}for(const name of ['model','version','color','interior','engine','dms','coc','warehouse','location','parking','notes']){if(!data[name]?.trim()){$('modal-error').textContent='Điền đầy đủ các trường thông tin.';return}}const oldVIN=c.vin;Object.assign(c,Object.fromEntries(Object.entries(data).map(([k,v])=>[k,String(v).trim()])));c.vin=newVIN;if(selectedVIN===oldVIN){selectedVIN=c.vin;drawerModel=c.model}log(c,'Quản trị viên chỉnh sửa thông tin xe mẫu.')}else if(a==='delete'){if(!data.reason?.trim()){$('modal-error').textContent='Cần nhập lý do xóa.';return}stock=stock.filter(o=>o!==c);persist()}$('action-dialog').close();refresh();message(a==='map'?'Đã đóng vị trí GPS.':'Đã cập nhật dữ liệu thử trong trình duyệt · Không tác động kho thật.')};
$('cancel-action').onclick=()=>$('action-dialog').close();$('close-drawer').onclick=closeDrawer;$('drawer-overlay').onclick=e=>{if(e.target===$('drawer-overlay'))closeDrawer()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('action-dialog').open&&!$('drawer-overlay').hidden){e.preventDefault();closeDrawer()}if(e.key==='Tab'&&!$('drawer-overlay').hidden&&!$('action-dialog').open){const list=Array.from($('drawer-overlay').querySelectorAll('button,input,select,a[href]')).filter(el=>!el.disabled&&el.getClientRects().length);const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('stock-search').oninput=e=>{keyword=e.target.value;renderStock()};$('warehouse-filter').onchange=e=>{warehouseChoice=e.target.value;renderStock()};$('drawer-search').oninput=e=>{drawerSearch=e.target.value;renderDrawer()};$('drawer-status').onchange=e=>{drawerStatus=e.target.value;renderDrawer()};$('drawer-version').onchange=e=>{drawerVersion=e.target.value;renderDrawer()};$('role').onchange=e=>{mode=e.target.value;renderStock();renderDrawer()};$('reset-demo').onclick=()=>{if($('action-dialog').open)$('action-dialog').close();stock=seedVehicles();keyword='';statusChoice='';warehouseChoice='';$('stock-search').value='';$('warehouse-filter').value='';refresh();message('Đã khôi phục 25 xe mẫu, trong đó VF 6 có 20 VIN.')};$('export-demo').onclick=()=>{const fields=detailFields(stock[0]).map(f=>f[0]);const rows=[fields,...filteredStock().map(c=>detailFields(c).map(f=>f[1]))];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='kho-xe-mau-day-du.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>message('Bản thử giao diện Kho xe.'));renderStock();
'''
css += '.detail-actions{position:sticky;top:0;z-index:2;background:#fff;border-bottom:1px solid var(--line);padding:12px 0;margin-bottom:4px}.demo-settings .quota-select{padding:7px;font-size:10px}.vin-detail{scroll-padding-top:65px}'
css += '''
.demo-main>*:not(.demo-gallery){flex-shrink:0}
.demo-gallery{flex:1 1 0;min-height:0;grid-auto-rows:max-content;align-items:start;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}
.group-card{overflow:visible;min-height:min-content}
dialog{max-height:calc(100dvh - 36px);overflow-y:auto}
.demo-head{gap:20px}.demo-settings{flex-wrap:wrap;justify-content:flex-end}
@media(max-width:1100px){.demo-head{align-items:flex-start}.demo-settings{max-width:440px;gap:8px}.demo-banner{gap:12px;line-height:1.6}.demo-banner span:last-child{display:none}}
'''
js=js.replace("if(readonly()){message('Tài khoản chỉ xem không được thay đổi dữ liệu.');return}","if(readonly()&&b.dataset.action!=='map'){message('Tài khoản chỉ xem không được thay đổi dữ liệu.');return}")
js=js.replace("function guard(c,a){if(readonly())return false;","function guard(c,a){if(a==='map')return true;if(readonly())return false;")
js=js.replace("bindActions($('vin-detail'));", "const stickyActions=$('vin-detail').querySelector('.detail-actions');if(stickyActions)$('vin-detail').querySelector('.detail-tabs').after(stickyActions);bindActions($('vin-detail'));")
js=js.replace(r"'\\ufeff'",r"'\ufeff'").replace(r".join('\\r\\n')",r".join('\r\n')")
js=js.replace("let mode='staff',", "let holdQuota=3;let mode='staff',")
js=js.replace('<button class="btn" id="reset-demo">','<label>Hạn mức giữ mẫu <select id="hold-quota" class="quota-select"><option>3</option><option>5</option><option>6</option></select></label><button class="btn" id="reset-demo">')
js=js.replace("const readonly=()=>mode==='readonly';", "const readonly=()=>mode==='readonly';const canHold=()=>mode==='admin'||stock.filter(c=>c.status==='Đang giữ'&&isMine(c)).length<holdQuota;")
js=js.replace("if(c.status==='Chưa ghép')out=button('hold','Giữ xe (24h)',true);", "if(c.status==='Chưa ghép')out=canHold()?button('hold','Giữ xe (24h)',true):'<button class=\"btn small\" disabled>Hết lượt giữ xe</button>';")
js=js.replace("if(a==='hold')return c.status==='Chưa ghép';", "if(a==='hold')return c.status==='Chưa ghép'&&canHold();")
js += "$('hold-quota').onchange=e=>{holdQuota=Number(e.target.value);renderStock();renderDrawer()};"
html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+js+'</script></body>')
html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu 21 · Danh sách VIN đầy đủ')
(root/'public/previews/kho-xe-mau-21.html').write_text(html,encoding='utf-8')
